1	"use server";
2	
3	// "use server" surface for the custom-plan builder — every export here is a
4	// public network endpoint the moment it exists, so EVERY one starts with its own
5	// `requireUser()` (see lib/order.ts serverLimitError's doc for exactly why a
6	// helper that skips this is a HAZARD test/auth-lockouts.test.ts exists to catch).
7	//
8	// This module owns no money movement: `confirmCustomPlanAction` /
9	// `confirmCustomGamePlanAction` only create the one-off catalog row (a real
10	// `Plan`/`GamePlan`, see lib/custom-plan.ts) the customer then buys through the
11	// EXACT same `payAndDeploy` / `payAndDeployGame` path every premade plan uses —
12	// so the actual charge, capacity re-check, wallet debit and invoice are all
13	// handled by code this feature does not touch at all.
14	import { z } from "zod";
15	import { requireUser, assertNotImpersonating } from "./auth";
16	import { GAME_FAMILIES } from "./games";
17	import {
18	  CustomPlanError,
19	  createCustomGamePlan,
20	  createCustomPlan,
21	  customPlanCapacityCheck,
22	  customPlanQuote,
23	} from "./custom-plan";
24	
25	const specSchema = z.object({
26	  cpuCores: z.coerce.number().int().min(1).max(4096),
27	  ramMB: z.coerce.number().int().min(1).max(8 * 1024 * 1024),
28	  diskGB: z.coerce.number().int().min(1).max(1_000_000),
29	});
30	
31	export type CustomPlanQuoteResult = {
32	  ok: boolean;
33	  error?: string;
34	  priceCents?: number;
35	  floor?: { cpuCores: number; ramMB: number; diskGB: number; priceCents: number };
36	  ceiling?: { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
37	  capacityOk?: boolean;
38	  capacityReason?: string;
39	};
40	
41	/**
42	 * Read-only live quote for the deploy wizard's custom-spec sliders — the
43	 * AUTHORITATIVE price/guardrail/capacity check, run right before the customer is
44	 * allowed to confirm a custom spec (the client-side computeCustomPlanPriceCents
45	 * call that drives the slider's live number as it moves is a preview only; this
46	 * is what actually gates the "Use this custom plan" button).
47	 */
48	export async function quoteCustomPlanAction(input: {
49	  cpuCores: number;
50	  ramMB: number;
51	  diskGB: number;
52	}): Promise<CustomPlanQuoteResult> {
53	  await requireUser();
54	  const parsed = specSchema.safeParse(input);
55	  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
56	  const quote = await customPlanQuote(parsed.data);
57	  if (!quote.ok) return { ok: false, error: quote.reason, floor: quote.floor, ceiling: quote.ceiling };
58	  const cap = await customPlanCapacityCheck(parsed.data);
59	  return {
60	    ok: true,
61	    priceCents: quote.priceCents,
62	    floor: quote.floor,
63	    ceiling: quote.ceiling,
64	    capacityOk: cap.ok,
65	    capacityReason: cap.reason,
66	  };
67	}
68	
69	export type ConfirmedCustomPlan = {
70	  id: string;
71	  name: string;
72	  cpuCores: number;
73	  ramMB: number;
74	  diskGB: number;
75	  bandwidthTB: number;
76	  priceCents: number;
77	  storageTier: string;
78	};
79	
80	/**
81	 * Create the one-off VPS `Plan` row for this exact spec. Called ONCE, when the
82	 * customer commits to their custom build (not on every slider tick) — the
83	 * returned plan's `id` then flows through the wizard's existing `planId` state
84	 * exactly like picking any premade plan card, so Location/Install/Access/Review/
85	 * Payment need no changes at all.
86	 */
87	export async function confirmCustomPlanAction(input: {
88	  cpuCores: number;
89	  ramMB: number;
90	  diskGB: number;
91	}): Promise<{ ok: boolean; error?: string; plan?: ConfirmedCustomPlan }> {
92	  await requireUser();
93	  try {
94	    await assertNotImpersonating();
95	  } catch (e) {
96	    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
97	  }
98	  const parsed = specSchema.safeParse(input);
99	  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
100	  try {
101	    const plan = await createCustomPlan(parsed.data);
102	    return { ok: true, plan };
103	  } catch (e) {
104	    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
105	    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
106	  }
107	}
108	
109	const gameConfirmSchema = specSchema.extend({
110	  gameFamily: z.enum(GAME_FAMILIES),
111	  players: z.coerce.number().int().min(1).max(1_000_000).optional(),
112	});
113	
114	export type ConfirmedCustomGamePlan = {
115	  gamePlanId: string;
116	  name: string;
117	  cpuCores: number;
118	  ramMB: number;
119	  diskGB: number;
120	  slots: number | null;
121	  priceCents: number;
122	  termMonths: number;
123	};
124	
125	/** Game analogue of `confirmCustomPlanAction` — creates the base `Plan` AND the
126	 *  `GamePlan` tier riding on it, returning the tier id the wizard drops straight
127	 *  into its existing `gamePlanId` hidden field. */
128	export async function confirmCustomGamePlanAction(input: {
129	  cpuCores: number;
130	  ramMB: number;
131	  diskGB: number;
132	  gameFamily: string;
133	  players?: number;
134	}): Promise<{ ok: boolean; error?: string; tier?: ConfirmedCustomGamePlan }> {
135	  await requireUser();
136	  try {
137	    await assertNotImpersonating();
138	  } catch (e) {
139	    return { ok: false, error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
140	  }
141	  const parsed = gameConfirmSchema.safeParse(input);
142	  if (!parsed.success) return { ok: false, error: "Invalid configuration." };
143	  try {
144	    const created = await createCustomGamePlan({
145	      spec: { cpuCores: parsed.data.cpuCores, ramMB: parsed.data.ramMB, diskGB: parsed.data.diskGB },
146	      gameFamily: parsed.data.gameFamily,
147	      players: parsed.data.players ?? null,
148	    });
149	    return {
150	      ok: true,
151	      tier: {
152	        gamePlanId: created.gamePlanId,
153	        name: created.name,
154	        cpuCores: created.plan.cpuCores,
155	        ramMB: created.plan.ramMB,
156	        diskGB: created.plan.diskGB,
157	        slots: created.slots,
158	        priceCents: created.priceCents,
159	        termMonths: 1,
160	      },
161	    };
162	  } catch (e) {
163	    if (e instanceof CustomPlanError) return { ok: false, error: e.message };
164	    return { ok: false, error: "Couldn't set up that custom server. Please try again." };
165	  }
166	}
