59	export default async function NxDeployPage() {
60	  const user = await requireUser();
61	
62	  // Exit-intent 25%-off popup eligibility (Feature: EXIT25). "First-time
63	  // customer" is the codebase's own established predicate for exactly this
64	  // kind of gate — zero non-free `Server` rows — already enforced identically
65	  // by `firstTimeOnly` coupon checks in lib/order.ts and
66	  // lib/coupon-redemption.ts. Resolved HERE, server-side, and threaded down as
67	  // a plain boolean prop: the deploy page is already a server component
68	  // reading `user`, so there is no reason to let the client decide something
69	  // this consequential on its own.
70	  const [isFirstTimeCustomer, exitIntentEnabled] = await Promise.all([
71	    db.server.count({ where: { userId: user.id, isFree: false } }).then((n) => n === 0),
72	    getSettingBool("exit_intent_enabled", true),
73	  ]);
74	
75	  // Real, per-customer eligibility for the first-month-free hosting promo —
76	  // NOT a display detail, the exact same advisory pre-check
77	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
78	  // wizard's hosting/email price was a flat, precomputed matrix with zero
79	  // per-user awareness (deliberately: "so there is no round-trip to make"),
80	  // which is why the promo's own plan-card badge ("First month free") and
81	  // the wizard's actual total disagreed — the matrix could not have known
82	  // whether THIS customer still qualifies. One extra check here, resolved
