340	      o.gameVariant =
341	        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
342	          ? intent.gameVariant
343	          : g.defaultVariant;
344	    }
345	  }
346	
347	  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
348	    o.hostingPlanId = intent.hostingPlanId;
349	  }
350	
351	  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
352	    o.emailPlanId = intent.emailPlanId;
353	  }
354	
355	  return o;
