263	  return (
264	    /* `overflow-x-auto` was already here, but `justify-center` on a flex row
265	       that overflows is a well-known trap: the browser centers the content
266	       BEFORE laying out the scrollable area, so the steps before whatever
267	       lands at `scrollLeft: 0` sit at a negative x-offset — reachable by
268	       scrolling right from the middle, but `scrollLeft` can never go
269	       negative, so the earliest step(s) were permanently unreachable, not
270	       just visually cramped. `justify-start` below the phone breakpoint
271	       gives the scroll area a real, reachable 0 at the actual first step;
272	       `sm:justify-center` keeps the original centered look once the whole
273	       rail fits without scrolling. */
274	    <ol className="noscroll mx-auto flex w-full max-w-[720px] items-start justify-start gap-0 overflow-x-auto px-2 sm:justify-center">
