/**
 * Shared /contact category map — imported by both the client form (labels) and
 * the server action (routing). `box` is the local part of the mailbox a category
 * routes to on the platform mail domain (support@ / contact@ / admin@).
 */
export const CONTACT_CATEGORIES = {
  support: { label: "Technical support", box: "support", hint: "Something not working, or a how-to question" },
  bug: { label: "Report a bug", box: "admin", hint: "Found a defect on the platform" },
  sales: { label: "Sales & plans", box: "contact", hint: "Pricing, plans, migrations, partnerships" },
  billing: { label: "Billing", box: "admin", hint: "Invoices, payments, refunds" },
  general: { label: "General enquiry", box: "contact", hint: "Anything else" },
} as const;

export type ContactCategory = keyof typeof CONTACT_CATEGORIES;

export const CONTACT_CATEGORY_ORDER: ContactCategory[] = ["support", "bug", "sales", "billing", "general"];
"use server";

import { z } from "zod";
import { headers } from "next/headers";
import { db } from "./db";
import { clientIp } from "./rate-limit";
import { sendMail } from "./mailer";
import { supportEmail } from "./settings";
import { escapeHtml } from "./site-render";
import { CONTACT_CATEGORIES } from "./contact-categories";

/**
 * Public /contact form. Each submission is validated, persisted (audit trail +
 * per-IP rate limiting), and emailed to the mailbox its category routes to —
 * so the message lands in support@ / contact@ / admin@ and shows up in the
 * in-portal inbox for that mailbox. Reply-To is the sender, so a team member
 * can reply straight from the mailbox.
 *
 * Never throws: returns a typed result the client renders inline.
 */

export type ContactResult = {
  ok: boolean;
  message: string;
};

const schema = z.object({
  name: z.string().trim().min(1, "Please enter your name.").max(120),
  email: z.email("That doesn’t look like a valid email.").max(200),
  category: z.enum(["support", "bug", "sales", "billing", "general"]),
  message: z.string().trim().min(10, "Please add a little more detail (at least 10 characters).").max(5000),
});

export type ContactInput = {
  name: string;
  email: string;
  category: string;
  message: string;
  company?: string; // honeypot
};

/** Derive the mailbox address a category routes to, on the platform's mail domain. */
async function routeAddress(box: string): Promise<string> {
  const support = await supportEmail(); // e.g. support@nxeon.cloud
  const domain = support.includes("@") ? support.split("@")[1] : "nxeon.cloud";
  return `${box}@${domain}`;
}

export async function submitContact(input: ContactInput): Promise<ContactResult> {
  // Honeypot tripped — pretend success, send nothing. Bots think they won.
  if (typeof input?.company === "string" && input.company.trim()) {
    return { ok: true, message: "Thanks — your message is on its way. We’ll get back to you shortly." };
  }

  const parsed = schema.safeParse({
    name: input?.name,
    email: typeof input?.email === "string" ? input.email.trim().toLowerCase() : input?.email,
    category: input?.category,
    message: input?.message,
  });

  if (!parsed.success) {
    const first = parsed.error.issues[0]?.message ?? "Please check the form and try again.";
    return { ok: false, message: first };
  }

  const { name, email, category, message } = parsed.data;

  // Attested client IP for rate limiting + the audit row. `clientIp` reads the
  // hop nginx actually appended — never the caller-supplied leftmost
  // X-Forwarded-For entry, which is free-text a bot rotates to buy a fresh
  // allowance every request. Falls back to a shared UNKNOWN bucket, never null.
  let ip: string | null = null;
  try {
    ip = clientIp(await headers());
  } catch {
    ip = null;
  }

  // Rate limit: max 5 submissions in 10 minutes from the same IP or email.
  try {
    const since = new Date(Date.now() - 10 * 60 * 1000);
    const recent = await db.contactMessage.count({
      where: {
        createdAt: { gte: since },
        OR: [...(ip ? [{ ip }] : []), { email }],
      },
    });
    if (recent >= 5) {
      return { ok: false, message: "You’ve sent a few messages already — please give us a little time to reply before sending more." };
    }
  } catch {
    // If the rate-limit read fails, fail open — don't block a real customer.
  }

  const routedTo = await routeAddress(CONTACT_CATEGORIES[category].box);
  const label = CONTACT_CATEGORIES[category].label;

  // Deliver to the routed mailbox. Reply-To = sender so the team replies directly.
  const html = `
    <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;font-size:15px;color:#0f172a;line-height:1.6">
      <p style="margin:0 0 4px"><strong>New ${escapeHtml(label)} enquiry</strong> from the Nxeon contact form.</p>
      <table style="border-collapse:collapse;margin:12px 0">
        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Name</td><td><strong>${escapeHtml(name)}</strong></td></tr>
        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Email</td><td><a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a></td></tr>
        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Category</td><td>${escapeHtml(label)}</td></tr>
      </table>
      <div style="white-space:pre-wrap;border-left:3px solid #6f47f5;padding:8px 14px;background:#f8fafc;border-radius:6px">${escapeHtml(message)}</div>
      <p style="margin:16px 0 0;color:#94a3b8;font-size:13px">Reply to this email to respond to ${escapeHtml(name)} directly.</p>
    </div>`;

  const delivered = await sendMail({
    to: routedTo,
    replyTo: email,
    subject: `[Nxeon · ${label}] ${name}`,
    html,
  });

  // Persist regardless of delivery so nothing is silently lost.
  try {
    await db.contactMessage.create({
      data: { name, email, category, message, routedTo, delivered, ip },
    });
  } catch (e) {
    console.error("[contact] failed to persist message:", e);
  }

  if (!delivered) {
    // The row is saved; an operator can still see it. Tell the user honestly.
    return {
      ok: true,
      message: "Thanks — we’ve received your message and it’s logged with our team. If you don’t hear back soon, email us directly.",
    };
  }

  return {
    ok: true,
    message: `Thanks, ${name.split(" ")[0]}! Your message is with our ${label.toLowerCase()} team — we’ll reply within one business day.`,
  };
}
