"use client";

import { useEffect, useMemo, useState } from "react";
import { Icon, Plate } from "./Icon";
import { Pick } from "./OrderBits";
import { useMoney } from "./useMoney";
import { useOrder } from "./order";
import type { CustomPlanConfig, GameTier, PlanOption, TermOption } from "./order-types";
import type { ConfigField } from "@/lib/game-config";
import {
  clampCustomPlanSpec,
  computeCustomPlanPriceCents,
  validateCustomPlanSpec,
  type CustomPlanSpec,
} from "@/lib/custom-plan-pricing";
import { playerSliderMax, recommendedSpecForPlayers } from "@/lib/game-player-recommend";
import type { GameFamily } from "@/lib/games";
import {
  confirmCustomGamePlanAction,
  confirmCustomPlanAction,
  quoteCustomPlanAction,
} from "@/lib/actions-custom-plan";

/* ── "Build a custom server" for the Nexion deploy wizard ────────────────────
 *
 * The backend already existed (lib/custom-plan*.ts, lib/actions-custom-plan.ts)
 * and the OLD wizards used it; this is the Nexion wizard's front end for it.
 *
 * Money rules, same as the rest of the wizard:
 *  - The number that moves under the slider is a PREVIEW from the one shared
 *    formula (computeCustomPlanPriceCents) — instant, no round trip.
 *  - Continue is gated on the AUTHORITATIVE quote (quoteCustomPlanAction:
 *    guardrails + real capacity check) for exactly the spec on screen.
 *  - Continuing creates the one-off Plan/GamePlan row server-side
 *    (confirmCustom*Action re-validates floor/ceiling/capacity from scratch),
 *    and from there it is bought through the normal quote → payAndDeploy /
 *    payAndDeployGame path like any catalogue plan. Nothing here charges.
 *
 * "Too big?" — anything past the self-serve ceiling, a failed capacity check,
 * or simply a customer who would rather talk it through, gets a clear route to
 * sales (/contact?topic=custom, pre-filled with what they had dialled in).
 */

const DISK_STEP_GB = 10;

/** Cheapest real custom build: one unit over the floor on the cheapest
 *  dimension — through the same formula, so "from $X" is never a guess. */
function minCustomPriceCents(cfg: CustomPlanConfig): number {
  const f = cfg.floor;
  const base = { cpuCores: f.cpuCores, ramMB: f.ramMB, diskGB: f.diskGB };
  return Math.min(
    computeCustomPlanPriceCents({ ...base, cpuCores: base.cpuCores + 1 }, f, cfg.rates),
    computeCustomPlanPriceCents({ ...base, ramMB: base.ramMB + 1024 }, f, cfg.rates),
    computeCustomPlanPriceCents({ ...base, diskGB: base.diskGB + DISK_STEP_GB }, f, cfg.rates),
  );
}

const gb = (mb: number) => Math.round(mb / 1024);
const specLine = (s: { cpuCores: number; ramMB: number; diskGB: number }) =>
  `${s.cpuCores} vCPU · ${gb(s.ramMB)} GB RAM · ${s.diskGB} GB NVMe`;

/** The game engine's own player ceiling, where the family's config schema
 *  declares one (its "Max players" field's `max`). Nxeon imposes no cap of its
 *  own — this is the game's, and the only honest ceiling to show. */
export function engineMaxPlayers(fields: ConfigField[] | undefined): number | null {
  const f = (fields ?? []).find((x) => x.type === "int" && /max\s*players?/i.test(x.label) && typeof x.max === "number");
  return f?.max ?? null;
}

/** The copy the owner asked for, in one place so every surface says the same. */
export const NO_PLAYER_CAP_NOTE =
  "No player cap from us — limited only by your server's resources and the game's own maximum.";

/* ── the tile that sits beside the plan / tier cards ─────────────────────── */
export function CustomPlanTile({ cfg, kind, built, on, open, termMonths, onClick }: {
  cfg: CustomPlanConfig;
  kind: "vps" | "game";
  /** The custom plan/tier already built this session, if any. */
  built: (PlanOption | GameTier) | null;
  /** The built custom plan is the one currently selected. */
  on: boolean;
  /** The builder panel is open. */
  open: boolean;
  termMonths: number;
  onClick: () => void;
}) {
  const money = useMoney();
  const from = minCustomPriceCents(cfg);
  const builtMonthly = built
    ? (kind === "vps" ? built.termMonthlyCents?.[termMonths] : undefined) ?? built.monthlyCents
    : null;
  const players = built && "slots" in built ? built.slots : null;
  return (
    <Pick on={on || open} onClick={onClick} aria-expanded={open}
          className="relative flex flex-col gap-3 p-3.5">
      <span className="absolute -top-[9px] left-3.5 rounded-full bg-[linear-gradient(100deg,#0e8fb0,#3b6be8)]
                       px-2.5 py-[3px] text-[10px] font-extrabold uppercase tracking-[0.07em] text-white">
        Build your own
      </span>
      <span className="flex flex-col gap-0.5">
        <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">Custom</span>
        <span className="text-[11.5px] text-tx-faint">
          {built ? specLine(built) : "Bigger than our plans, sized to you"}
        </span>
      </span>

      <span className="flex items-baseline gap-1.5">
        {!built && <span className="text-[11.5px] text-tx-dim">from</span>}
        <span className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[25px] text-transparent">
          {money(builtMonthly ?? from)}
        </span>
        <span className="text-[11.5px] text-tx-dim">/mo</span>
      </span>

      <ul className="flex flex-col gap-1.5">
        {built ? (
          <>
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="cpu" size={14} className="flex-none opacity-85" />{built.cpuCores} vCPU
            </li>
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="ram" size={14} className="flex-none opacity-85" />{gb(built.ramMB)} GB RAM
            </li>
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="database" size={14} className="flex-none opacity-85" />{built.diskGB} GB NVMe
            </li>
            {players != null && (
              <li className="flex items-center gap-2 text-[12px] text-tx-body">
                <Icon name="users" size={14} className="flex-none opacity-85" />Recommended for ~{players} players
              </li>
            )}
          </>
        ) : (
          <>
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="sliders" size={14} className="flex-none opacity-85" />Choose your own vCPU, RAM &amp; disk
            </li>
            {kind === "game" && (
              <li className="flex items-center gap-2 text-[12px] text-tx-body">
                <Icon name="users" size={14} className="flex-none opacity-85" />Sized from your player count
              </li>
            )}
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="tag" size={14} className="flex-none opacity-85" />See what each resource costs
            </li>
            <li className="flex items-center gap-2 text-[12px] text-tx-body">
              <Icon name="handshake" size={14} className="flex-none opacity-85" />Bigger still? Talk to sales
            </li>
          </>
        )}
      </ul>
      <span className={"btn-ghost mt-auto h-[36px] w-full rounded-[9px] text-[12.5px] " +
                       (on ? "border-transparent bg-[linear-gradient(100deg,#1a55cf,#6f2ee0)] text-white" : "")}>
        {open ? "Close builder" : on ? "Selected · edit" : built ? "Edit custom build" : "Build a custom server"}
      </span>
    </Pick>
  );
}

/* ── one resource slider row ─────────────────────────────────────────────── */
function ResourceSlider({ icon, label, value, unit, min, max, step, extra, rateCents, rateUnit, onChange }: {
  icon: string; label: string; value: number; unit: string;
  min: number; max: number; step: number;
  /** Units above the floor — what is actually being paid for. */
  extra: number; rateCents: number; rateUnit: string;
  onChange: (n: number) => void;
}) {
  const money = useMoney();
  const pct = max > min ? ((value - min) / (max - min)) * 100 : 0;
  const atMax = value >= max;
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2.5">
        <Plate name={icon} size={18} />
        <span className="flex min-w-0 flex-1 flex-col leading-[1.3]">
          <span className="text-[12.5px] font-bold text-white">{label}</span>
          <span className="text-[10.8px] text-tx-faint">
            {money(rateCents)}/{rateUnit} per month above the base
          </span>
        </span>
        <span className="flex flex-none flex-col items-end leading-[1.3]">
          <span className="text-[14px] font-extrabold text-white tabular-nums">{value} {unit}</span>
          <span className={"text-[10.8px] tabular-nums " + (atMax ? "text-amber" : "text-tx-faint")}>
            {atMax ? "Self-serve max" : extra > 0 ? `+${money(extra * rateCents)}/mo` : "Included"}
          </span>
        </span>
      </div>
      <input type="range" aria-label={`${label} (${unit})`}
             min={min} max={max} step={step} value={value}
             onChange={(e) => onChange(+e.target.value)}
             className="range w-full"
             style={{ "--pct": `${pct}%` } as React.CSSProperties} />
    </div>
  );
}

/* ── the builder panel ───────────────────────────────────────────────────── */
type QuoteState =
  | { key: string; status: "checking" }
  | { key: string; status: "ok"; priceCents: number; termMonthlyCents: Record<number, number>; capacityOk: boolean; capacityReason?: string }
  | { key: string; status: "bad"; reason: string };

export function CustomServerBuilder({ cfg, kind, family, familyName, checkoutFields, terms, onBuilt, onClose }: {
  cfg: CustomPlanConfig;
  kind: "vps" | "game";
  /** Game orders only. */
  family?: string;
  familyName?: string;
  checkoutFields?: ConfigField[];
  terms: TermOption[];
  /** Called after the custom row exists and has been selected. */
  onBuilt: () => void;
  onClose: () => void;
}) {
  const { o, cat, applyCustomPlan, applyCustomTier } = useOrder();
  const money = useMoney();
  const { floor, ceiling, rates } = cfg;
  const isGame = kind === "game" && !!family;

  // Start from the build already made this session, if there is one, so
  // "Edit custom build" reopens on what the customer chose — not a reset.
  const existing: (PlanOption | GameTier) | null = isGame
    ? cat.games.find((g) => g.family === family)?.tiers.find((t) => t.custom) ?? null
    : cat.plans.find((p) => p.custom) ?? null;

  const engineMax = isGame ? engineMaxPlayers(checkoutFields) : null;
  const sliderMax = isGame
    ? Math.max(2, Math.min(playerSliderMax(family as GameFamily), engineMax ?? Infinity))
    : 0;

  /* Round a recommendation onto the sliders' own grid (whole GB of RAM, 10 GB
     of disk above the floor) and clamp into floor..ceiling. If that lands on
     the floor exactly — i.e. the headcount fits a standard plan — nudge RAM up
     1 GB so the spec is a real custom build (a floor-identical spec is just
     "Max" and the server rightly refuses it). */
  const fromPlayers = (players: number): { spec: CustomPlanSpec; overCeiling: boolean; fitsStandard: boolean } => {
    const rec = recommendedSpecForPlayers(family as GameFamily, players);
    const raw: CustomPlanSpec = {
      cpuCores: rec.cpuCores,
      ramMB: Math.ceil(rec.ramMB / 1024) * 1024,
      diskGB: floor.diskGB + Math.ceil(Math.max(0, rec.diskGB - floor.diskGB) / DISK_STEP_GB) * DISK_STEP_GB,
    };
    const overCeiling = raw.cpuCores > ceiling.maxCpuCores || raw.ramMB > ceiling.maxRamMB || raw.diskGB > ceiling.maxDiskGB;
    const fitsStandard = raw.cpuCores <= floor.cpuCores && raw.ramMB <= floor.ramMB && raw.diskGB <= floor.diskGB;
    let spec = clampCustomPlanSpec(raw, floor, ceiling);
    if (spec.cpuCores === floor.cpuCores && spec.ramMB === floor.ramMB && spec.diskGB === floor.diskGB) {
      spec = clampCustomPlanSpec({ ...spec, ramMB: spec.ramMB + 1024 }, floor, ceiling);
    }
    return { spec, overCeiling, fitsStandard };
  };

  const initialPlayers = isGame
    ? (existing && "slots" in existing && existing.slots ? Math.min(existing.slots, sliderMax) : Math.max(1, Math.round(sliderMax / 2)))
    : 0;
  const [players, setPlayers] = useState<number>(initialPlayers);
  const [playersTouched, setPlayersTouched] = useState<boolean>(false);
  const [spec, setSpec] = useState<CustomPlanSpec>(() => {
    if (existing) return { cpuCores: existing.cpuCores, ramMB: existing.ramMB, diskGB: existing.diskGB };
    if (isGame) return fromPlayers(initialPlayers).spec;
    // VPS: open one clear step up from the top plan (double it), not on the
    // floor itself — the floor alone is just "Max" and can't be ordered here.
    return clampCustomPlanSpec(
      { cpuCores: floor.cpuCores * 2, ramMB: floor.ramMB * 2, diskGB: floor.diskGB * 2 }, floor, ceiling);
  });
  const playerInfo = isGame ? fromPlayers(players) : null;

  const setPlayersAndSpec = (n: number) => {
    setPlayers(n);
    setPlayersTouched(true);
    setSpec(fromPlayers(n).spec);
  };
  const setDim = (k: keyof CustomPlanSpec, v: number) =>
    setSpec((s) => clampCustomPlanSpec({ ...s, [k]: v }, floor, ceiling));

  const specKey = `${spec.cpuCores}/${spec.ramMB}/${spec.diskGB}`;
  const valid = validateCustomPlanSpec(spec, floor, ceiling);
  const preview = computeCustomPlanPriceCents(spec, floor, rates);

  /* The authoritative check, debounced behind the slider. Keyed by spec so a
     slow reply for a spec the customer has already moved past is ignored. */
  const [quote, setQuote] = useState<QuoteState | null>(null);
  useEffect(() => {
    if (!valid.ok) { setQuote(null); return; }
    let cancelled = false;
    const key = specKey;
    setQuote({ key, status: "checking" });
    const t = setTimeout(async () => {
      try {
        const res = await quoteCustomPlanAction(spec);
        if (cancelled) return;
        if (!res.ok || res.priceCents == null) setQuote({ key, status: "bad", reason: res.error ?? "That configuration isn't available." });
        else setQuote({
          key, status: "ok", priceCents: res.priceCents,
          termMonthlyCents: res.termMonthlyCents ?? {},
          capacityOk: !!res.capacityOk, capacityReason: res.capacityReason,
        });
      } catch {
        if (!cancelled) setQuote({ key, status: "bad", reason: "Couldn't check that right now — try again in a moment." });
      }
    }, 450);
    return () => { cancelled = true; clearTimeout(t); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [specKey, valid.ok]);
  const current = quote && quote.key === specKey ? quote : null;
  const confirmedPrice = current?.status === "ok" ? current.priceCents : null;
  const capacityBad = current?.status === "ok" && !current.capacityOk;
  const canContinue = valid.ok && current?.status === "ok" && current.capacityOk;

  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  async function build() {
    if (!canContinue || busy) return;
    setBusy(true); setErr(null);
    try {
      if (isGame) {
        const res = await confirmCustomGamePlanAction({
          ...spec, gameFamily: family!, players: playersTouched || existing ? players : undefined,
        });
        if (!res.ok || !res.tier) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
        const t = res.tier;
        applyCustomTier(family!, {
          id: t.gamePlanId,
          // Display name only — the DB row's name carries the family key as a
          // suffix for admin views, which reads oddly in the customer's cart.
          name: `Custom · ${t.cpuCores} vCPU / ${gb(t.ramMB)} GB`,
          ramMB: t.ramMB, cpuCores: t.cpuCores, diskGB: t.diskGB,
          slots: t.slots,
          monthlyCents: t.priceCents,
          termMonths: t.termMonths,
          introMonthlyCents: null, introRenewalMonthlyCents: null,
          termMonthlyCents: t.termMonthlyCents,
        });
      } else {
        const res = await confirmCustomPlanAction(spec);
        if (!res.ok || !res.plan) { setErr(res.error ?? "Couldn't set up that custom server."); return; }
        const p = res.plan;
        applyCustomPlan({
          id: p.id, slug: "custom", name: `Custom · ${p.cpuCores} vCPU / ${gb(p.ramMB)} GB`,
          cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: p.bandwidthTB,
          monthlyCents: p.priceCents,
          // Same basis as the catalogue plans' `effectiveMonthlyCents` (the
          // monthly-term rate); the per-term figures ride in termMonthlyCents.
          effectiveMonthlyCents: p.termMonthlyCents[1] ?? p.priceCents,
          introMonthlyCents: null, introRenewalMonthlyCents: null,
          termMonthlyCents: p.termMonthlyCents,
        });
      }
      onBuilt();
    } catch {
      setErr("Couldn't set up that custom server — please try again.");
    } finally {
      setBusy(false);
    }
  }

  /* Why the sales card should be the headline rather than a footnote. */
  const atAnyMax = spec.cpuCores >= ceiling.maxCpuCores || spec.ramMB >= ceiling.maxRamMB || spec.diskGB >= ceiling.maxDiskGB;
  const salesReason: string | null =
      playerInfo?.overCeiling ? `~${players} players needs more than our self-serve maximum (${ceiling.maxCpuCores} vCPU · ${gb(ceiling.maxRamMB)} GB · ${ceiling.maxDiskGB} GB).`
    : capacityBad ? (current?.status === "ok" ? current.capacityReason ?? "We don't have room for this size right now." : null)
    : atAnyMax ? "You're at our self-serve maximum on at least one resource."
    : null;

  const salesHref = useMemo(() => {
    const lines = [
      "Custom server request (from the deploy wizard)",
      `Product: ${isGame ? `Game server — ${familyName ?? family}` : "Cloud VPS"}`,
      ...(isGame ? [`Players: ~${players}`] : []),
      `Spec I was looking at: ${spec.cpuCores} vCPU / ${gb(spec.ramMB)} GB RAM / ${spec.diskGB} GB disk`,
      `Billing term: ${terms.find((t) => t.months === o.termMonths)?.label ?? `${o.termMonths} months`}`,
      ...(salesReason ? [`Note: ${salesReason}`] : []),
      "",
      "What I need: ",
    ];
    return `/contact?topic=custom&message=${encodeURIComponent(lines.join("\n"))}`;
  }, [isGame, familyName, family, players, spec, terms, o.termMonths, salesReason]);

  const extraCpu = Math.max(0, spec.cpuCores - floor.cpuCores);
  const extraRamGb = Math.max(0, gb(spec.ramMB - floor.ramMB));
  const extraDisk = Math.max(0, spec.diskGB - floor.diskGB);
  const shownPrice = confirmedPrice ?? preview;
  const termLabel = terms.find((t) => t.months === o.termMonths)?.label ?? "";
  const termMonthly = current?.status === "ok" ? current.termMonthlyCents[o.termMonths] : undefined;

  return (
    <div className="card flex flex-col gap-4 p-4" id="custom-builder">
      <div className="flex items-start gap-3">
        <Plate name="serverscale" size={24} />
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">
            Build a custom {isGame ? `${familyName ?? "game"} server` : "server"}
          </span>
          <span className="text-[11.8px] leading-[1.45] text-tx-faint">
            Starts above our largest plan ({specLine(floor)}, {money(floor.priceCents)}/mo). You pay that base,
            plus a flat rate for each resource you add on top.
          </span>
        </span>
        <button type="button" onClick={onClose} aria-label="Close custom builder"
                className="flex-none text-tx-faint hover:text-white">
          <Icon name="xcircle" size={16} />
        </button>
      </div>

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)]">
        {/* ── left: the dials ── */}
        <div className="flex flex-col gap-4">
          {isGame && (
            <div className="flex flex-col gap-2 rounded-[10px] border border-rim-soft bg-well p-3">
              <div className="flex items-center gap-2.5">
                <Plate name="users" size={18} />
                <span className="flex min-w-0 flex-1 flex-col leading-[1.3]">
                  <span className="text-[12.5px] font-bold text-white">How many players?</span>
                  <span className="text-[10.8px] text-tx-faint">Sets recommended resources below — adjust anything after</span>
                </span>
                <span className="flex-none text-[16px] font-extrabold text-white tabular-nums">~{players}</span>
              </div>
              <input type="range" aria-label="Expected players"
                     min={1} max={sliderMax} step={1} value={players}
                     onChange={(e) => setPlayersAndSpec(+e.target.value)}
                     className="range w-full"
                     style={{ "--pct": `${((players - 1) / Math.max(1, sliderMax - 1)) * 100}%` } as React.CSSProperties} />
              <span className="text-[11px] leading-[1.45] text-tx-faint">
                {playerInfo?.fitsStandard
                  ? <>~{players} players fits our standard {familyName ?? ""} plans above — they&apos;re the better deal. Custom starts at the size shown here.</>
                  : <>A recommendation, not a limit. {NO_PLAYER_CAP_NOTE}</>}
                {engineMax != null && <> {familyName ?? "This game"} itself supports up to {engineMax} players per server.</>}
              </span>
            </div>
          )}

          <ResourceSlider icon="cpu" label="vCPU" unit="vCPU" value={spec.cpuCores}
                          min={floor.cpuCores} max={ceiling.maxCpuCores} step={1}
                          extra={extraCpu} rateCents={rates.perVcpuCents} rateUnit="vCPU"
                          onChange={(n) => setDim("cpuCores", n)} />
          <ResourceSlider icon="ram" label="Memory" unit="GB" value={gb(spec.ramMB)}
                          min={gb(floor.ramMB)} max={gb(ceiling.maxRamMB)} step={1}
                          extra={extraRamGb} rateCents={rates.perRamGbCents} rateUnit="GB"
                          onChange={(n) => setDim("ramMB", n * 1024)} />
          <ResourceSlider icon="database" label="NVMe disk" unit="GB" value={spec.diskGB}
                          min={floor.diskGB} max={ceiling.maxDiskGB} step={DISK_STEP_GB}
                          extra={extraDisk} rateCents={rates.perDiskGbCents} rateUnit="GB"
                          onChange={(n) => setDim("diskGB", n)} />
        </div>

        {/* ── right: the price, itemised ── */}
        <div className="flex flex-col gap-3 rounded-[10px] border border-rim-soft bg-well p-3.5">
          <span className="nx-label uppercase">Your custom server</span>
          <span className="flex items-baseline gap-1.5">
            <span className={"num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[30px] text-transparent transition-opacity " +
                             (confirmedPrice === null ? "opacity-60" : "")}>
              {money(shownPrice)}
            </span>
            <span className="text-[12px] text-tx-dim">/mo</span>
          </span>
          {o.termMonths > 1 && termMonthly !== undefined && (
            <span className="-mt-2 text-[11px] text-tx-faint">
              {money(termMonthly)}/mo effective on {termLabel.toLowerCase()} billing
            </span>
          )}

          <ul className="flex flex-col gap-1.5 text-[12px]">
            <li className="flex items-baseline justify-between gap-3">
              <span className="text-tx-mute">Base · {specLine(floor)}</span>
              <span className="flex-none font-semibold text-white tabular-nums">{money(floor.priceCents)}</span>
            </li>
            <li className="flex items-baseline justify-between gap-3">
              <span className="text-tx-mute">+{extraCpu} vCPU × {money(rates.perVcpuCents)}</span>
              <span className="flex-none font-semibold text-white tabular-nums">{money(extraCpu * rates.perVcpuCents)}</span>
            </li>
            <li className="flex items-baseline justify-between gap-3">
              <span className="text-tx-mute">+{extraRamGb} GB RAM × {money(rates.perRamGbCents)}</span>
              <span className="flex-none font-semibold text-white tabular-nums">{money(extraRamGb * rates.perRamGbCents)}</span>
            </li>
            <li className="flex items-baseline justify-between gap-3">
              <span className="text-tx-mute">+{extraDisk} GB disk × {money(rates.perDiskGbCents)}</span>
              <span className="flex-none font-semibold text-white tabular-nums">{money(extraDisk * rates.perDiskGbCents)}</span>
            </li>
            <li className="flex items-baseline justify-between gap-3">
              <span className="text-tx-mute">Transfer</span>
              <span className="flex-none font-semibold text-white">{floor.bandwidthTB} TB included</span>
            </li>
          </ul>

          <span className="rule" />

          {/* Status of the authoritative check, in words. */}
          <div aria-live="polite" className="min-h-[18px] text-[11.8px] leading-[1.45]">
            {!valid.ok ? (
              <span className="flex items-start gap-1.5 text-amber"><Icon name="warntriangle" size={13} className="mt-[1px] flex-none" />{valid.reason}</span>
            ) : !current || current.status === "checking" ? (
              <span className="flex items-center gap-1.5 text-tx-faint"><Icon name="clock2" size={13} className="flex-none animate-spin opacity-70" />Checking price and capacity…</span>
            ) : current.status === "bad" ? (
              <span className="flex items-start gap-1.5 text-rose"><Icon name="xcircle" size={13} className="mt-[1px] flex-none" />{current.reason}</span>
            ) : current.capacityOk ? (
              <span className="flex items-center gap-1.5 text-mint"><Icon name="checkcircle" size={13} className="flex-none" />Price confirmed · we have room for this now</span>
            ) : (
              <span className="flex items-start gap-1.5 text-rose"><Icon name="xcircle" size={13} className="mt-[1px] flex-none" />{current.capacityReason ?? "We don't have room for a server this size right now."}</span>
            )}
          </div>

          {err && (
            <div className="flex items-start gap-2 rounded-[8px] border border-[rgba(239,66,108,0.3)] bg-[rgba(239,66,108,0.08)] px-3 py-2 text-[12px] text-rose">
              <Icon name="xcircle" size={14} className="flex-none" /><span>{err}</span>
            </div>
          )}

          <button type="button" onClick={build} disabled={!canContinue || busy}
                  className="btn h-[42px] w-full text-[13.5px] disabled:opacity-45">
            {busy ? "Setting it up…" : `Use this custom server`} {!busy && <span className="arw" aria-hidden>→</span>}
          </button>
          <span className="text-[10.8px] leading-[1.45] text-tx-faint">
            Nothing is charged here — you&apos;ll pick a location and pay on the next steps, like any plan.
          </span>
        </div>
      </div>

      {/* ── "too big?" → sales ── */}
      <div className={"flex flex-col gap-3 rounded-[10px] border p-3.5 sm:flex-row sm:items-center " +
                      (salesReason
                        ? "border-[rgba(239,168,40,0.4)] bg-[rgba(239,168,40,0.08)]"
                        : "border-rim-soft bg-well")}>
        <Plate name="handshake" size={22} />
        <span className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="text-[13px] font-bold text-white">
            {salesReason ? "Need more than this? Talk to sales" : "Rather talk it through? Talk to sales"}
          </span>
          <span className={"text-[11.5px] leading-[1.45] " + (salesReason ? "text-amber" : "text-tx-faint")}>
            {salesReason ?? "Bigger builds, several servers, or something bespoke — tell us what you need and a person will spec it with you."}
          </span>
        </span>
        <a href={salesHref} target="_blank" rel="noopener"
           className={(salesReason ? "btn" : "btn-ghost") + " h-[40px] flex-none px-4 text-[13px]"}>
          Talk to sales <span className="arw" aria-hidden>→</span>
        </a>
      </div>
    </div>
  );
}

