// Walk the Nexion deploy wizard's custom-server flow (no payment).
const { chromium } = require("/opt/nxeon/node_modules/playwright");
const fs = require("fs");
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/wiz/";
const BASE = "http://localhost:3034";
const creds = fs.readFileSync("/root/nxeon-staging-credentials.txt", "utf8");
const email = creds.match(/Email:\s*(\S+)/)[1];
const password = creds.match(/Password:\s*(\S+)/)[1];
const W = +(process.argv[2] || 1440);
const H = W < 600 ? 844 : 900;
const tag = W < 600 ? "390" : "1440";

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const logs = [];
  page.on("console", (m) => { if (m.type() === "error") logs.push("console: " + m.text()); });
  page.on("pageerror", (e) => logs.push("pageerror: " + e.message));
  const shot = async (n, full = false) => { await page.waitForTimeout(700); await page.screenshot({ path: `${OUT}${tag}-${n}.png`, fullPage: full }); console.log("shot", n); };

  await page.goto(BASE + "/login", { waitUntil: "domcontentloaded", timeout: 180000 });
  await page.fill('input[type="email"], input[name="email"]', email);
  await page.fill('input[type="password"]', password);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith("/login"), { timeout: 180000 }),
    page.click('button[type="submit"]'),
  ]);
  console.log("logged in ->", page.url());

  // ── VPS ──
  await page.goto(BASE + "/dashboard/deploy?product=vps", { waitUntil: "networkidle", timeout: 240000 });
  await page.waitForSelector("#s-configure", { timeout: 120000 });
  await shot("vps-1-plans");
  await page.locator("#s-configure button", { hasText: "Build a custom server" }).click();
  await page.waitForSelector("#custom-builder");
  await page.waitForSelector("text=Price confirmed", { timeout: 60000 }).catch(() => console.log("no price confirmed (vps)"));
  await page.locator("#custom-builder").scrollIntoViewIfNeeded();
  await shot("vps-2-builder");
  // drag CPU to max to trigger the sales emphasis
  const cpu = page.locator('#custom-builder input[aria-label^="vCPU"]');
  await cpu.evaluate((el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, el.max); el.dispatchEvent(new Event("input", { bubbles: true })); });
  await page.waitForSelector("text=Need more than this", { timeout: 10000 }).catch(() => console.log("no sales emphasis"));
  await page.waitForTimeout(1500);
  await shot("vps-3-at-max");
  const salesHref = await page.locator('#custom-builder a:has-text("Talk to sales")').getAttribute("href");
  console.log("sales href:", decodeURIComponent(salesHref));
  // back down, confirm
  await cpu.evaluate((el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, "8"); el.dispatchEvent(new Event("input", { bubbles: true })); });
  await page.waitForSelector("text=Price confirmed", { timeout: 60000 });
  await page.locator('#custom-builder button:has-text("Use this custom server")').click();
  await page.waitForSelector("#s-region[aria-hidden='false'], #s-region", { timeout: 60000 });
  await page.waitForTimeout(1500);
  await shot("vps-4-region-after-custom");
  // Next -> payment
  await page.locator("button:has-text('Next')").last().click();
  await page.waitForTimeout(3000);
  await shot("vps-5-payment", true);

  // ── contact prefill ──
  await page.goto(BASE + salesHref, { waitUntil: "domcontentloaded", timeout: 180000 });
  await page.waitForSelector("#cf-message", { timeout: 120000 });
  await page.locator("#cf-message").scrollIntoViewIfNeeded();
  await shot("contact-prefilled");

  // ── Game (Minecraft) ──
  await page.goto(BASE + "/dashboard/deploy?product=game&game=minecraft", { waitUntil: "networkidle", timeout: 240000 });
  const url = page.url();
  // choose minecraft via the grid if intent key differs
  if (!(await page.locator("#s-gconf").isVisible().catch(() => false)) || !(await page.locator("#s-gconf button", { hasText: "Build a custom server" }).count())) {
    await page.waitForSelector("#s-game", { timeout: 60000 });
    await page.locator("#s-game button", { hasText: "Minecraft" }).first().click();
  }
  await page.waitForSelector("#s-gconf button:has-text('Build a custom server')", { timeout: 60000 });
  await page.waitForTimeout(1200);
  await shot("game-0-picker-back", false);
  await page.locator("#s-gconf").scrollIntoViewIfNeeded();
  await shot("game-1-tiers");
  await page.locator("#s-gconf button", { hasText: "Build a custom server" }).click();
  await page.waitForSelector("#custom-builder");
  await page.waitForSelector("text=Price confirmed", { timeout: 60000 }).catch(() => console.log("no price confirmed (game)"));
  await page.locator("#custom-builder").scrollIntoViewIfNeeded();
  await shot("game-2-builder");
  const pl = page.locator('#custom-builder input[aria-label="Expected players"]');
  await pl.evaluate((el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, el.max); el.dispatchEvent(new Event("input", { bubbles: true })); });
  await page.waitForTimeout(1500);
  await shot("game-3-max-players");
  await pl.evaluate((el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, "10"); el.dispatchEvent(new Event("input", { bubbles: true })); });
  await page.waitForTimeout(1500);
  await shot("game-4-few-players");
  await pl.evaluate((el) => { const s = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; s.call(el, "150"); el.dispatchEvent(new Event("input", { bubbles: true })); });
  await page.waitForSelector("text=Price confirmed", { timeout: 60000 });
  await page.locator('#custom-builder button:has-text("Use this custom server")').click();
  await page.waitForSelector("#custom-builder", { state: "detached", timeout: 60000 });
  await page.locator("#s-gconf").scrollIntoViewIfNeeded();
  await shot("game-5-custom-selected");
  // fill subdomain + go on
  const sub = page.locator('#s-gconf input[placeholder="myserver"]');
  if (await sub.count()) await sub.fill("cstest" + Date.now().toString(36).slice(-5));
  await page.waitForTimeout(2500);
  await page.locator("button:has-text('Next')").last().click();
  await page.waitForTimeout(1500);
  await shot("game-6-region");
  await page.locator("button:has-text('Next')").last().click();
  await page.waitForTimeout(3500);
  await shot("game-7-payment", true);

  console.log("errors:\n" + logs.join("\n"));
  await browser.close();
})().catch((e) => { console.error("FAILED", e); process.exit(1); });

